button.p{font-size:14px;padding:9px 16px;border-width:2px}
.h{font-size:13px;margin:8px 0 0;padding:8px;border-left:3px solid rgba(128,128,128,.6);line-height:1.45}
.m{font-size:12px;opacity:.7;margin-left:8px}
</style>
<div id="cards"></div>
<button class="p" onclick="send()">Send my answers for a verdict</button>
<span class="m" id="st"></span>
<script>
const Q=[
["Rank by SN2 rate (fastest to slowest): 1-bromobutane, 2-bromobutane, 2-bromo-2-methylpropane.",
["SN2 is a one-step backside attack. Ask what is sitting around the carbon bearing the halogen, in the nucleophile's way.","Parallel case: rank chloromethane, chloroethane, 2-chloropropane. Count the carbon groups on the C–Cl carbon and think about crowding in the transition state. Then apply the same logic to your three."]],
["Which is the better leaving group, Cl⁻ or I⁻? Why?",
["A leaving group departs carrying the electron pair. Ask what makes an anion comfortable on its own.","Parallel case: which is the weaker base, F⁻ or Br⁻, and what about size and charge spread explains it? Does the same trend apply to Cl⁻ vs I⁻?"]],
["Predict the product of sodium ethoxide with iodomethane.",
["Label the nucleophile and the electrophile first. Which atom in each is doing the work?","Parallel case: hydroxide with chloromethane. Push the arrows, say what bond forms and what leaves, then write the product's functional group. Do the same with ethoxide."]],
["Why does DMSO speed up SN2 compared with methanol?",
["Think about the nucleophile, not the substrate. What is surrounding an anion like Br⁻ in each solvent?","Parallel case: why is F⁻ a much more reactive nucleophile in acetone than in water? Compare what each solvent can and can't do to an anion."]],
["What happens to the stereocenter in (R)-2-bromobutane with NaCN?",
["Which side of the carbon does the nucleophile approach from, relative to the leaving group? Sketch it and track the other three groups.","Caution: the geometry and the R/S label are two different things. After you sketch the product, reassign CIP priorities from scratch rather than assuming the label from the geometry."]]
];
const used=Q.map(()=>0);
const el=document.getElementById('cards');
Q.forEach((q,i)=>{
 const d=document.createElement('div');d.className='c';
 d.innerHTML=`<p class="q"><b>${i+1}.</b> ${q[0]}</p><textarea id="a${i}" placeholder="Your answer and reasoning"></textarea><div style="margin-top:8px"><button onclick="hint(${i})">Hint</button><span class="m" id="m${i}"></span></div><div id="h${i}"></div>`;
 el.appendChild(d);
});
function hint(i){
 if(used[i]>=2)return;
 const p=document.createElement('p');p.className='h';p.textContent=Q[i][1][used[i]];
 document.getElementById('h'+i).appendChild(p);
 used[i]++;
 document.getElementById('m'+i).textContent=used[i]+' of 2 hints used';
}
function send(){
 let t="Here are my answers to the practice set:\n\n";
 Q.forEach((q,i)=>{
  const a=document.getElementById('a'+i).value.trim();
  t+=(i+1)+". "+(a||"(no answer)")+" [hints used: "+used[i]+"]\n";
 });
 t+="\nGive me a verdict on each (right, partly right, or not yet) and then work with me on the weakest one.";
 document.getElementById('st').textContent='Sent.';
 sendPrompt(t);
}
</script>
</div>
